function waveparam = idealeccd_dke_jd(xyrho,xythetab,xyn,xyopt,xyNpar,xydNpar,xypol,xyomega_rf,xyPinc,xyfinc,Te_ref,ne_ref,Bt,Rp,ap,bounce_mode);%% Calculates the normalized diffusion coefficient for ideal, low density limit limit ECCD polarization (mostly for comparison)%   - X-Mode: polarization [1/sqrt(2),1/sqrt(2),0] %   - O-Mode: polarization [0,0,1] %% by J. Decker 05/02/03%qe = 1.6022e-19;%Electron charge (C)me = 9.1094e-31;%Electron rest mass (Kg)mp = 1.6726e-27;%Proton rest mass (Kg)e0 = 8.8542e-12;%Free space permeability (F/m)%[nr,nb] = size(xyrho);%xyia = xyrho*ap/Rp;xyB = Bt./(1 + xyia.*cos(xythetab));xywce = qe*xyB/me;%xyNperp = sqrt(1 - xyNpar.^2); %low density limit%% note: polarization + neglected herexyepolp = zeros(nr,nb); xyepolm = (xypol/sqrt(2) + 0*~xypol); xyepolz = (0*xypol + ~xypol);xyepolk = zeros(nr,nb); %no longitudinal component: low density limit%% electron frequencies%wpe_ref = sqrt(ne_ref*qe^2/e0/me);xywce0 = qe*Bt./(1 + xyia)/me;%lnc_ref = 15.2 - 0.5*log(ne_ref/1e20) + log(Te_ref);%xypsib = (1 + xyia)./(1 + xyia.*cos(xythetab));xypsic = (1 + xyia);%if bounce_mode == 0 %     xywce_out = xywce0.*xypsib;    xyrpsi = ones(nr,nb);else    xywce_out = xywce0;    xyrpsi = xypsib./xypsic;end%xyphibdn = (1 - abs(xyepolk).^2).*sqrt(xyNpar.^2 + xyNperp.^2)./xyfinc;%xyD0 = xyPinc.*xyrpsi./(me*wpe_ref^2*lnc_ref*xyomega_rf.*abs(xyphibdn).*xyrho*ap*Rp);%    % --------------------------- building waveparam-----------------------%    waveparam = zeros(nr,nb,14);%waveparam(:,:,1) = xyn;%RF resonance harmonic     waveparam(:,:,2) = xyomega_rf;%RF wave frequencywaveparam(:,:,3) = xywce_out;%midplane cyclotron frequency (r,theta=0) at the radial position considered waveparam(:,:,4) = xyopt;%options for Larmor radius effects and/or LH calc. waveparam(:,:,5) = xythetab;%poloidal location of RF beam (relevant for bounce_mode>0 only)    waveparam(:,:,6) = xyD0;%RF quasi-linear diffusion coefficient (nhuth_ref*pth_ref^2)waveparam(:,:,7) = NaN*ones(nr,nb);%Square N// spectrum: Lower limitwaveparam(:,:,8) = NaN*ones(nr,nb);%Square N// spectrum: Upper limitwaveparam(:,:,9) = xyNpar;%Gaussian N// spectrum: peak n//waveparam(:,:,10) = xydNpar;%Gaussian N// spectrum: width in n//waveparam(:,:,11) = xyNperp;%RF wave : n_perpwaveparam(:,:,12) = xyepolp;%RF wave : polarization pluswaveparam(:,:,13) = xyepolm;%RF wave : polarization minuswaveparam(:,:,14) = xyepolz;%RF wave : polarization parallel